SELECT DISTINCT h.name
FROM Highschooler h
WHERE EXISTS (
    SELECT 1 FROM Friend f WHERE f.student_id = h.ID
)
AND EXISTS (
    SELECT 1 FROM Likes l WHERE l.liked_id = h.ID
);

SELECT conductor.Name, orchestra.Orchestra
FROM conductor
JOIN orchestra ON conductor.Conductor_ID = orchestra.Conductor_ID;

SELECT d.Document_Name, d.Template_ID
FROM Documents d
WHERE d.Document_Description LIKE '%w%';
